// Helper: Simpson's rule on interval [l, r] using precomputed f(l), f(m), f(r)
auto simpson = [&](double l, double r, double fl, double fm, double fr) -> double {
    return (r - l) * (fl + 4.0 * fm + fr) / 6.0;
};

// Recursive adaptive Simpson implementation
std::function<double(double, double, double, double, double, double, double)> adapt;
adapt = [&](double l, double r, double fl, double fm, double fr,
            double whole, double eps) -> double {
    double m  = 0.5 * (l + r);
    double lm = 0.5 * (l + m);
    double rm = 0.5 * (m + r);
    double flm = f(lm);
    double frm = f(rm);
    double left  = simpson(l, m, fl, flm, fm);
    double right = simpson(m, r, fm, frm, fr);
    double delta = left + right - whole;
    if (std::abs(delta) <= 15.0 * eps) {
        // Richardson extrapolation for higher accuracy
        return left + right + delta / 15.0;
    }
    // Subdivide further, halving tolerance for each subinterval
    double leftRes  = adapt(l, m, fl, flm, fm, left, eps * 0.5);
    double rightRes = adapt(m, r, fm, frm, fr, right, eps * 0.5);
    return leftRes + rightRes;
};

// Initial evaluation
double fa = f(a);
double fb = f(b);
double m  = 0.5 * (a + b);
double fm = f(m);
double initial = simpson(a, b, fa, fm, fb);

